import{readFileSync,writeFileSync,mkdirSync,existsSync}from'node:fs';import{resolve,join}from'node:path';import{createRequire}from'node:module';import assert from'node:assert/strict';import{LocalModelCache,localCoreIdentity,localExtractionKey}from'../../../../src/analyze/local-model-cache.ts';import{createProblemExecutor}from'../../../../src/analyze/execute-problem.ts';import{runAnalysisDsl}from'../../../../src/analyze/run-analysis-dsl.ts';
const [packet]=process.argv.slice(2);const base=resolve('debugging/p6-p7-integration',packet),out=join(base,'model-reuse');mkdirSync(out,{recursive:true});process.env.PCB_ANALYSIS_CACHE_DIR=join(base,'cache');
const boardJson=JSON.stringify(JSON.parse(readFileSync('tests/pcb-analyze/STM32G0_CAN_RS485/STM32G0_CAN_RS485.json','utf8'))),geometry=JSON.parse(readFileSync('tests/fixtures/analysis-local-extraction/board-integration/single-method-via-request.json','utf8'));
const execute=createProblemExecutor(true);const request={boardJson,geometry,bandHz:[1000,100000] as[number,number],frequenciesHz:[1000,10000,100000]};
const key=localExtractionKey(new LocalModelCache(join(base,'cache')),localCoreIdentity(),{boardJson,geometry,bandHz:[1000,100000]});if(!existsSync(join(base,'cache',key+'.json')))throw Error('Run final cold first: exact model cache entry absent; refusing surprise field preparation');
const started=performance.now();const first=execute({kind:'local-extraction',request});const opposite=execute({kind:'local-extraction',request:{...request,drive:[1,-1]}});const loaded=execute({kind:'local-extraction',request:{...request,drive:[1,-1],loadsOhm:[1000,1000]}});
assert.equal(first.cache.status,'disk');for(const value of [opposite,loaded]){assert.equal(value.cache.status,'memory');assert.equal(value.cache.assembly,0);assert.equal(value.cache.training,0);assert.equal(value.cache.key,first.cache.key);}
assert.notDeepEqual(opposite.samples,loaded.samples);const pdnResult=JSON.parse(readFileSync(join(base,'TPS63060DSCR','cold','result.json'),'utf8'));
const pdnCold=pdnResult.reports.flatMap((r:any)=>r.plots).find((p:any)=>p.title.startsWith('Cold stage')).data;
const pdnRequest={boardJson:JSON.stringify(JSON.parse(readFileSync('tests/pcb-analyze/TPS63060DSCR/TPS63060DSCR.json','utf8'))),geometry:{...geometry,roiMm:pdnCold.prepared.request.roiMm,electrodes:pdnCold.prepared.request.electrodes,ports:pdnCold.prepared.request.ports},bandHz:[1000,100000] as[number,number],frequenciesHz:[1000,10000,100000]};
const pdnKey=localExtractionKey(new LocalModelCache(join(base,'cache')),localCoreIdentity(),pdnRequest);if(!existsSync(join(base,'cache',pdnKey+'.json')))throw Error('Exact PDN cache absent; refusing surprise field preparation');
const pdn=execute({kind:'local-extraction',request:pdnRequest}),pdnLoaded=execute({kind:'local-extraction',request:{...pdnRequest,drive:[1,-1],loadsOhm:[10,20]}});
assert.equal(pdn.cache.status,'disk');assert.equal(pdnLoaded.cache.status,'memory');assert.equal(pdnLoaded.cache.key,pdn.cache.key);assert.equal(pdnLoaded.cache.assembly,0);assert.equal(pdnLoaded.cache.training,0);assert.notDeepEqual(pdn.samples,pdnLoaded.samples);
writeFileSync(join(out,'pdn.json'),JSON.stringify({ports:pdnCold.prepared.request.ports,mapping:pdnCold.prepared.mapping,base:pdn,loaded:pdnLoaded}));

const native=new(createRequire(import.meta.url)('../../../../native/node-addon/index.cjs').AnalysisElectricalSession)();
writeFileSync(join(out,'recovery.json'),JSON.stringify({phase:'before-dc',first:first.cache,opposite,loaded}));
let dc:any,dcError:string|undefined,unitDcRejected=false,power:number|undefined,dcPowerCheck:boolean|undefined;
try{dc=native.solveLocal({prepared:first.prepared,frequenciesHz:[0],drive:[1,-1]});power=dc.samples[0].portRealV[0]-dc.samples[0].portRealV[1];dcPowerCheck=Math.abs(power!-dc.samples[0].totalLossW)/Math.max(Math.abs(power!),1e-18)<1e-8;}catch(e){dcError=String(e);}
try{native.solveLocal({prepared:first.prepared,frequenciesHz:[0],drive:[1,0]});}catch{unitDcRejected=true;}

const resource={id:'actual-extracted-stm32',kind:'network',ports:['input','output'],analyses:['networkParameters','si'],validity:{status:'conditional',reason:'Local extracted RLC, accepted electric v1; complete field/full-reduced verification separate',domain:{bandHz:[1000,100000]}},data:first.model};
const code=`const a=analysis();const n=a.network({model:models.electrical.local,ports:{input:'input',output:'output'}});const t=await a.si().network(n).drivers([{port:n.port('input'),model:{kind:'linear-driver',lowV:0,highV:.001,outputResistanceOhm:1000},stimulus:{kind:'waveform',voltageV:{kind:'step',from:0,to:.001,atS:0,riseS:1e-4}}}]).receivers([{port:n.port('output'),model:{kind:'rc-input',capacitanceF:1e-12,resistanceOhm:1000}}]).time({stopS:.001,sampleStepS:5e-5}).numerics({relativeTolerance:1e-5,absoluteTolerance:1e-10,maxStepS:1e-5}).budget({maxSeconds:60,maxMemoryMiB:512}).run();a.plot({title:'Slow finite-ramp response of the actual extracted passive RLC',data:t.voltage(n.port('output'))});a.check({name:'Loaded DC limit of connected via, within declared slow-input hypothesis',actual:t.voltage(n.port('output')).at({timeS:.001}),target:.0005,tolerance:.000025,unit:'V'});a.plot({title:'Temporal guards and original provenance',kind:'table',data:t.solution});`;
const temporal=await runAnalysisDsl({code,models:{electrical:{local:resource}} as any},{timeoutMs:65000,maxOutputBytes:32*1024*1024});
writeFileSync(join(out,'recovery.json'),JSON.stringify({wallSeconds:(performance.now()-started)/1000,first:first.cache,opposite:{cache:opposite.cache,samples:opposite.samples},loaded:{cache:loaded.cache,samples:loaded.samples},dc,dcError,dcPowerCheck,unitDcRejected}));writeFileSync(join(out,'temporal.json'),JSON.stringify(temporal));console.log(JSON.stringify({cache:[first.cache,opposite.cache,loaded.cache],unitDcRejected,dcPower:power,dcLoss:dc?.samples[0].totalLossW,dcError,dcPowerCheck,temporalStatus:temporal.status,error:temporal.error}));
